test('revision conflict refreshes options, keeps input and requires a new preview',async()=>{const b=await create();b.run("businessAPI.open('lead.create');businessAPI.change(['name'],'张同学');businessAPI.change(['phone'],'13812345678');businessAPI.change(['source'],'来电')");b.respondBusiness(async url=>url.endsWith('/preview')?response({code:'REVISION_CONFLICT',message:'资料已更新'},409):response(snapshot(2)));assert.equal(await b.run('businessAPI.preview()'),false);assert.equal(b.run('businessAPI.status().revision'),2);assert.match(b.elements.get('#view').innerHTML,/value="张同学"/);assert.equal(await b.run('businessAPI.execute()'),false)});
test('late business responses cannot repopulate records after logout',async()=>{const b=await create();let release;b.respondBusiness(async url=>url.endsWith('/v1/state')?new Promise(r=>release=r):url.endsWith('/v1/catalog')?response({operations:[...operations,...moreOperations]}):response({}));const load=b.run('businessAPI.reload()');await b.run('employeeAuth.logout()');release(response(snapshot(9)));await load;assert.equal(b.run('a.students.length'),0);assert.equal(b.run('businessAPI.snapshot()'),null);assert.equal(b.run('businessAPI.status().revision'),null)});
test('unimplemented or unauthorized operations cannot appear executable or call local mutations',async()=>{const b=await create();assert.equal(b.run("businessAPI.open('unknown.operation')"),false);b.run("businessAPI.open('lead.create')");const before=b.run('JSON.stringify(businessAPI.snapshot())');assert.equal(b.run('workflowPersist()'),false);assert.equal(b.run('JSON.stringify(businessAPI.snapshot())'),before);assert.equal(b.run("workflowSearchEntries('转移').length"),0);assert.equal(b.run("workflowSearchEntries('创建线索')[0].label"),'创建线索')});
test('authenticated request adapter rejects external endpoints and does not export CSRF',async()=>{const b=await create();await assert.rejects(b.run("employeeAuth.request('https://evil.invalid')"));await assert.rejects(b.run("employeeAuth.request('v1/../admin')"));assert.equal(b.run('employeeAuth.csrf'),undefined);assert.equal(b.run('JSON.stringify(businessAPI.status())').includes('private-csrf'),false)});
async function realBusiness({permissions}={}){const {BusinessStore}=require('../backend/src/business-store.cjs'),store=new BusinessStore(':memory:'),registry=['academic','crm','commerce'].flatMap(n=>require('../backend/src/business-'+n+'.cjs').operations),actor={...user,id:'real-admin',roleIds:['superadmin'],permissions:permissions||[...new Set([...registry.map(o=>o.permission),'settings.read','course.read','class.read','student.read','lead.read','order.read','schedule.read'])]},teacher={id:'real-teacher',name:'真实老师',roleIds:['teacher'],permissions:['session.attendance','session.record'],scope:{type:'all'},disabled:false},b=await authCreate(actor);b.respond(async(url,options={})=>{try{url=String(url);if(url.endsWith('/v1/catalog'))return response({operations:registry.map(({run,...o})=>({...o,implemented:true,execution:'server'}))});if(url.endsWith('/v1/state')){const snap=store.snapshot();return response({...snap,state:{...snap.state,directory:[teacher,actor]},capabilities:{businessReady:true,paymentProvider:false}})}const match=url.match(/operations\/([^/]+)\/(preview|execute)$/);if(match){const op=registry.find(o=>o.id===decodeURIComponent(match[1])),body=JSON.parse(options.body);return response(match[2]==='preview'?store.preview(op,body.input,actor,[teacher,actor],body.expectedRevision):store.execute(op,body.input,actor,[teacher,actor],{revision:body.expectedRevision,previewToken:body.previewToken,key:options.headers['Idempotency-Key']}))}return response({})}catch(e){return response({code:e.code,message:e.message},e.status||400)}});b.run(code);await new Promise(r=>setImmediate(r));return {...b,store,registry,teacher,async commit(id,input){assert.equal(b.run(`businessAPI.open(${JSON.stringify(id)})`),true,id);for(const [k,v]of Object.entries(input))b.run(`businessAPI.change([${JSON.stringify(k)}],${JSON.stringify(v)})`);assert.equal(await b.run('businessAPI.preview()'),true,id+': '+b.run('businessAPI.status().error'));assert.equal(await b.run('businessAPI.execute()'),true,id+': '+b.run('businessAPI.status().error'));return store.snapshot().state}}}
test('real backend roundtrip can create campus, course, class, student, enrollment and manual receipt entirely through UI adapter',async()=>{const b=await realBusiness();try{let state=await b.commit('campus.create',{name:'真实甲校区',rooms:[{name:'A101',capacity:20}]});const campusId=state.campuses[0].id;state=await b.commit('course.create',{name:'真实四年级数学',subject:'数学',grade:'4年级',priceCents:123456,lessons:[{title:'第一讲',durationMinutes:60}]});const course=state.courses[0];state=await b.commit('class.create',{name:'正式数学一班',courseId:course.id,campusId,room:'A101',teacherId:b.teacher.id,capacity:20});const classId=state.classes[0].id;state=await b.commit('class.schedule',{classId,sessions:[{lessonId:course.lessons[0].id,date:'2099-01-01',time:'09:00–10:00'}]});assert.equal(state.classes[0].schedule.length,1);state=await b.commit('student.create',{name:'真实学生',phone:'13800000001',grade:'4年级',campusId});state=await b.commit('enrollment.create',{studentId:state.students[0].id,classId});const order=state.orders[0];assert.equal(order.amountCents,123456);state=await b.commit('order.confirmReceipt',{orderId:order.id,amountCents:123456,reference:'BANK-REAL-001',method:'bank'});assert.equal(state.orders[0].paidCents,123456);assert.equal(b.run('a.orders[0].paidCents'),123456);assert.equal(b.run('a.students[0].name'),'真实学生');assert(!b.storage.has('siyue-workflow-demo-v2'));}finally{b.store.close()}});
test('all registered backend schemas open without missing references or JSON textareas, dynamic config and decor save through typed handlers',async()=>{const b=await realBusiness();try{for(const op of b.registry){assert.equal(b.run(`businessAPI.open(${JSON.stringify(op.id)})`),true,op.id);assert.ok(!b.elements.get('#view').innerHTML.includes('JSON'),op.id)}let state=await b.commit('settings.update',{section:'organization',values:{name:'正式机构',address:'正式地址'}});assert.equal(state.settings.organization.name,'正式机构');state=await b.commit('dictionary.update',{key:'subjects',values:['数学','语文']});assert.equal(state.dictionary.subjects[0],'数学');state=await b.commit('store.design.save',{decor:{title:'正式网校',subtitle:'欢迎咨询',color:'#315beb',modules:['介绍'],blocks:{介绍:{title:'机构简介',body:'真实课程咨询',image:'',cta:'了解课程'}}}});assert.equal(state.decor.draft.title,'正式网校');b.run("businessAPI.open('settings.update');businessAPI.change(['section'],'move')");assert.match(b.elements.get('#view').innerHTML,/限制同年级/);assert.match(b.elements.get('#view').innerHTML,/disabled/);}finally{b.store.close()}});
test('server schedule keeps teacher/student rectangular timelines and room/campus tables with session actions',async()=>{const b=await create(),data=snapshot();data.state.directory=[{id:'t1',name:'陈老师',roleIds:['teacher']}];data.state.classes[0]={...data.state.classes[0],teacherId:'t1',room:'一号教室',campusId:'site1',schedule:[{id:'session1',date:'2099-01-01',time:'09:00–10:00',lessonId:'lesson1',studentIds:['s1']}]};data.state.campuses=[{id:'site1',name:'甲校区',roomDetails:[{name:'一号教室'}]}];data.state.courses[0].lessons=[{id:'lesson1',title:'第一讲'}];data.state.enrollments=[{id:'e1',studentId:'s1',classId:'cl1',status:'active'}];b.respondBusiness(async url=>response(url.endsWith('/state')?data:{operations}));await b.run('businessAPI.reload()');b.run("nav('schedule')");let h=b.elements.get('#view').innerHTML;assert.match(h,/caterpillar-board/);assert.match(h,/worm-segment/);assert.match(h,/陈老师/);b.run("SiyueBusinessSchedule.filter('mode','student')");assert.match(b.elements.get('#view').innerHTML,/服务器学生/);b.run("SiyueBusinessSchedule.filter('mode','room')");h=b.elements.get('#view').innerHTML;assert.match(h,/<th>教室<\/th>/);assert(!h.includes('caterpillar-board'));assert.match(h,/一号教室/)});
test('live decor keeps iPhone preview and independent module inspector; staff and referral use names',async()=>{const b=await realBusiness();try{let state=await b.commit('store.design.save',{decor:{title:'正式商城',subtitle:'欢迎',color:'#315beb',modules:['介绍','课程'],blocks:{介绍:{title:'单独介绍',body:'介绍内容'},课程:{title:'单独课程',body:'课程内容'}}}});b.run("nav('mallDecor');businessAPI.open('store.design.save');businessAPI.focusBlock('课程')");let h=b.elements.get('#view').innerHTML;assert.match(h,/iphone17/);assert.match(h,/单独课程/);assert.match(h,/恢复已保存草稿/);assert(!h.includes('value="单独介绍"'));b.run("businessAPI.change(['decor','blocks','课程','title'],'修改课程');businessAPI.restoreDecor()");assert.match(b.elements.get('#view').innerHTML,/value="单独课程"/);b.run("businessAPI.open('staff.profile.update')");assert.match(b.elements.get('#view').innerHTML,/value="real-teacher"[^>]*>真实老师/);b.run("nav('home')");h=b.elements.get('#view').innerHTML;const card=h.slice(h.indexOf('常用操作'));assert((card.match(/onclick="businessAPI.open/g)||[]).length<=6);}finally{b.store.close()}});
test('single-page new-student enrollment and mixed batch correction use typed rows without separate student creation',async()=>{const b=await realBusiness();try{let state=await b.commit('campus.create',{name:'单页报名校区',rooms:[{name:'A',capacity:20}]});const campusId=state.campuses[0].id;state=await b.commit('course.create',{name:'单页数学',grade:'4年级',subject:'数学',priceCents:10000,lessons:[{title:'一',durationMinutes:60}]});state=await b.commit('class.create',{name:'单页班',courseId:state.courses[0].id,campusId,teacherId:b.teacher.id,room:'A',capacity:20});const classId=state.classes[0].id;b.run(`businessAPI.open('enrollment.create');businessAPI.change(['classId'],${JSON.stringify(classId)});businessAPI.studentMode([],true);businessAPI.change(['studentDraft','name'],'新生甲');businessAPI.change(['studentDraft','phone'],'13800000011')`);assert.match(b.elements.get('#view').innerHTML,/学生信息/);assert.equal(await b.run('businessAPI.preview()'),true,b.run('businessAPI.status().error'));assert.equal(await b.run('businessAPI.execute()'),true);state=b.store.snapshot().state;assert.equal(state.students.length,1);assert.equal(state.orders.length,1);b.run(`businessAPI.open('enrollment.batchCreate');businessAPI.change(['classId'],${JSON.stringify(classId)});businessAPI.studentMode(['rows',0],true);businessAPI.change(['rows',0,'studentDraft','name'],'新生乙');businessAPI.change(['rows',0,'studentDraft','phone'],'bad')`);assert.equal(await b.run('businessAPI.preview()'),false);assert.equal(b.store.snapshot().state.students.length,1);assert.match(b.elements.get('#view').innerHTML,/联系电话格式无效|手机号/);assert.ok(!b.elements.get('#view').innerHTML.includes('密码需满足'));b.run("businessAPI.change(['rows',0,'studentDraft','phone'],'13800000012')");assert.equal(await b.run('businessAPI.preview()'),true,b.run('businessAPI.status().error'));assert.equal(await b.run('businessAPI.execute()'),true);assert.equal(b.store.snapshot().state.students.length,2);assert.equal(b.store.snapshot().state.orders.length,2);}finally{b.store.close()}});
test('account campus grants choose server records by name instead of requiring internal IDs',async()=>{const b=await realBusiness();try{await b.commit('campus.create',{name:'真实选项校区',rooms:[]});let posted;b.respond(async(url,options={})=>{if(options.method==='POST'){posted=JSON.parse(options.body);return response({user:{id:'new',name:posted.name,username:'new',roleIds:posted.roleIds,scope:posted.scope}})}return response(String(url).endsWith('/v1/roles')?{roles:[{id:'teacher',label:'老师'}],permissions:[]}:{users:[]})});await b.run('employeeAuth.openAccounts()');b.run('employeeAuth.newAccount()');assert.match(b.elements.get('#view').innerHTML,/name="ea-campus"/);assert.match(b.elements.get('#view').innerHTML,/真实选项校区/);assert.ok(!b.elements.get('#view').innerHTML.includes('id="ea-campuses"'));b.ctx.document.querySelector('#ea-name').value='新增老师';b.ctx.document.querySelector('#ea-scope').value='campus';b.lists.set('input[name="ea-role"]:checked',[{value:'teacher'}]);b.lists.set('input[name="ea-campus"]:checked',[{value:b.store.snapshot().state.campuses[0].id}]);await b.run('employeeAuth.saveAccount()');assert.equal(posted.scope.campusIds[0],b.store.snapshot().state.campuses[0].id);}finally{b.store.close()}});

