test('my leads uses current owner and separate active, enrolled and archived underline tabs',async()=>{const b=await leadViews();b.run("nav('myLeads')");assert.deepEqual(leadRowIds(b),['本人到期','本人未来预约','两项待办','刚分配','回收候选','近期有效沟通']);assert.match(b.elements.get('#view').innerHTML,/business-tabs/);b.run("businessAPI.leadTab('leadMineTab','converted')");assert.deepEqual(leadRowIds(b),['本人已报名']);b.run("businessAPI.leadTab('leadMineTab','archived')");assert.deepEqual(leadRowIds(b),['本人已归档']);assert.doesNotMatch(b.elements.get('#view').innerHTML,/data-lead-row="本人登记已转交"/);});
