test('student creation opens the existing enrollment form with the committed server student id and preserves back history across idempotent retry',async()=>{
 const b=await realBusiness();
 try{
  let state=await b.commit('campus.create',{name:'新生衔接校区',rooms:[{name:'A教室',capacity:20}]});
  const campusId=state.campuses[0].id;
  state=await b.commit('course.create',{name:'新生衔接数学',grade:'4年级',subject:'数学',priceCents:12800,lessons:[{title:'第一讲',durationMinutes:60}]});
  state=await b.commit('class.create',{name:'新生衔接班',courseId:state.courses[0].id,campusId,teacherId:b.teacher.id,room:'A教室',capacity:20});
  b.run("nav('students');businessAPI.open('student.create')");
  b.run("businessAPI.change(['name'],'自动衔接学生');businessAPI.change(['phone'],'13800000981')");
  assert.equal(await b.run('businessAPI.preview()'),true,b.run('businessAPI.status().error'));
  const originalFetch=b.ctx.fetch,keys=[];let failStateOnce=true;
  b.respond(async(url,options={})=>{
   const path=String(url);
   if(path.includes('/operations/student.create/execute'))keys.push(options.headers?.['Idempotency-Key']);
   if(failStateOnce&&path.endsWith('/v1/state')){failStateOnce=false;return response({code:'TEMPORARY_STATE_FAILURE',message:'temporary state read failure'},503)}
   return originalFetch(url,options);
  });
  assert.equal(await b.run('businessAPI.execute()'),false);
  assert.equal(b.run('businessAPI.status().operation'),'student.create');
  assert.equal(b.run('state.page'),'businessOperation');
  assert.equal(b.messages.some(message=>/档案已创建/.test(message)),false,'a failed state refresh must not announce successful creation');
  assert.equal(b.run('businessAPI.status().error').includes('重试确认提交结果'),true);
  assert.equal(b.store.snapshot().state.students.length,1,'the first request committed exactly one student');
  assert.equal(await b.run('businessAPI.execute()'),true,b.run('businessAPI.status().error'));
  const student=b.store.snapshot().state.students[0];
  assert.equal(b.store.snapshot().state.students.length,1,'idempotent retry did not create a duplicate');
  assert.deepEqual(keys,[keys[0],keys[0]],'retry reused the same idempotency key');
  assert.equal(b.run('businessAPI.status().operation'),'enrollment.create');
  assert.match(b.elements.get('#view').innerHTML,new RegExp(`value="${student.id}"[^>]*checked`));
  assert.match(b.elements.get('#view').innerHTML,/自动衔接学生/);
  assert.match(b.elements.get('#view').innerHTML,/新生衔接班/);
  assert.match(b.elements.get('#view').innerHTML,/\[&quot;classId&quot;\]/);
  assert.match(b.messages.at(-1),/已打开报名分班/);
  b.run('businessAPI.back()');
  assert.equal(b.run('state.page'),'students');
  assert.equal(b.run('businessAPI.status().operation'),null);
 }finally{b.store.close()}
});

